PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry tanh_fp16(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 N
)
{
    // Registers
    .reg .pred   %p0;
    .reg .b32    %r0, %r1, %r2, %r3, %r4, %r5, %r6;
    .reg .b64    %rd0, %rd1, %rd2, %rd3, %rd4, %rd5;
    .reg .f16    %f16in, %f16out;
    .reg .f32    %f32tmp;

    // Load kernel arguments
    ld.param.u64    %rd0, [input_ptr];   // input pointer
    ld.param.u64    %rd1, [output_ptr];  // output pointer
    ld.param.u32    %r0, [N];            // total number of elements

    // -----------------------------------------------------------------
    // Compute thread linear index: idx = blockIdx.x * blockDim.x + threadIdx.x
    // -----------------------------------------------------------------
    mov.u32         %r1, %ctaid.x;       // blockIdx.x
    mov.u32         %r2, %ntid.x;        // blockDim.x
    mov.u32         %r3, %tid.x;         // threadIdx.x
    mad.lo.s32      %r4, %r1, %r2, %r3;  // r4 = idx (32‑bit)
    cvt.u64.u32     %rd2, %r4;           // idx as 64‑bit

    // -----------------------------------------------------------------
    // Compute stride = gridDim.x * blockDim.x
    // -----------------------------------------------------------------
    mov.u32         %r5, %nctaid.x;      // gridDim.x
    mul.lo.s32      %r6, %r5, %r2;       // stride (32‑bit)
    cvt.u64.u32     %rd3, %r6;           // stride as 64‑bit

    // Convert N to 64‑bit for comparison
    cvt.u64.u32     %rd4, %r0;           // N (64‑bit)

    // -----------------------------------------------------------------
    // Main loop: each thread processes elements spaced by 'stride'
    // -----------------------------------------------------------------
.Loop:
    // if (idx >= N) break;
    setp.ge.u64     %p0, %rd2, %rd4;
    @%p0            bra.uni .Lexit;

    // Load fp16 element
    ld.global.f16   %f16in, [%rd0 + %rd2*2];

    // Convert to fp32, compute tanh, convert back to fp16
    cvt.f32.f16     %f32tmp, %f16in;
    tanh.approx.f32 %f32tmp, %f32tmp;
    cvt.f16.f32     %f16out, %f32tmp;

    // Store result
    st.global.f16   [%rd1 + %rd2*2], %f16out;

    // idx += stride;
    add.u64         %rd2, %rd2, %rd3;
    bra.uni         .Loop;

.Lexit:
    ret;
}
'''
