        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies the PTX tanh kernel to the input tensor.
        """
        assert x.dtype == torch.float16, "Model expects float16 inputs"
        out = torch.empty_like(x)

        # Total number of elements
        N = x.numel()
        # Choose launch configuration
        threads_per_block = 256
        blocks = (N + threads_per_block - 1) // threads_per_block

        # Launch the kernel
        ptx_launch(
            self.module,
            "tanh_fp16",
            (blocks, 1, 1),               # grid dimensions
            (threads_per_block, 1, 1),    # block dimensions
            [x.data_ptr(), out.data_ptr(), N]  # kernel arguments
        )
        return out
